namespace CheckoutPricing.Domain;

public static class LoyaltyDiscount
{
    private const int CeilingPoints = 10;

    public static int ForSubtotal(LoyaltyTier tier, int subtotalCents)
    {
        var points = Math.Min(BasePoints(tier) + OrderSizeBonusPoints(subtotalCents), CeilingPoints);
        return (int)((long)subtotalCents * points / 100);
    }

    private static int BasePoints(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 7,
        LoyaltyTier.Gold => 9,
        _ => throw new ArgumentOutOfRangeException(nameof(tier), tier, null)
    };

    private static int OrderSizeBonusPoints(int subtotalCents) => subtotalCents switch
    {
        >= 20000 => 3,
        >= 5000 => 1,
        _ => 0
    };
}
E
